// ============================================================
// VELLOSO - FILTRO E NORMALIZACAO DE LEADS
// Le duas planilhas CSV, filtra, normaliza e retorna leads validos
// ============================================================

const csv1 = $('HTTP - CSV Principal').first().json.data || '';
const csv2 = $json.data || '';

// --- Mapeamento de colunas ---
// Aliases atualizados com os nomes REAIS das colunas do CSV Principal:
// Colunas reais confirmadas: nome, biografia, celular, email
const ALIASES = {
  nome:       ['nome','name','nome completo','full name','cliente','contato'],
  telefone:   ['telefone','whatsapp','celular','fone','phone','tel','telefone/whatsapp','numero','numero','celular/whatsapp','telefone / whatsapp'],
  email:      ['email','e-mail','mail'],
  cidade:     ['cidade','city'],
  estado:     ['estado','state','uf'],
  profissao:  ['profissao','profissao','cargo','ocupacao','ocupacao','profession','area','area'],
  observacao: ['observacao','observacao','obs','notes','biografia','bio','descricao','descricao','sobre']
};

function normKey(k) {
  return String(k||'').toLowerCase().normalize('NFKD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');
}

const HEADER_MAP = {};
for (const [std, aliases] of Object.entries(ALIASES)) {
  aliases.forEach(a => { HEADER_MAP[normKey(a)] = std; });
}

// --- Deteccao automatica de delimitador ---
function detectDelimiter(text) {
  const firstLine = text.split('\n')[0] || '';
  const commas = (firstLine.match(/,/g) || []).length;
  const semis  = (firstLine.match(/;/g) || []).length;
  const tabs   = (firstLine.match(/\t/g) || []).length;
  if (tabs > commas && tabs > semis) return '\t';
  if (semis > commas) return ';';
  return ',';
}

// --- Parser CSV robusto ---
function parseCSV(text, delimiter) {
  if (!text || !text.trim()) return [];
  if (!delimiter) delimiter = detectDelimiter(text);
  const rows = [];
  let row = [], field = '', inQ = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i], n = text[i+1];
    if (c === '"') {
      if (inQ && n === '"') { field += '"'; i++; }
      else inQ = !inQ;
    } else if (c === delimiter && !inQ) {
      row.push(field); field = '';
    } else if ((c === '\n' || c === '\r') && !inQ) {
      if (c === '\r' && n === '\n') i++;
      row.push(field);
      if (row.some(v => String(v).trim())) rows.push(row);
      row = []; field = '';
    } else {
      field += c;
    }
  }
  row.push(field);
  if (row.some(v => String(v).trim())) rows.push(row);
  if (!rows.length) return [];
  const rawH = rows[0].map(h => normKey(h));
  const headers = rawH.map(h => HEADER_MAP[h] || h);
  return rows.slice(1).map(cols => {
    const obj = {};
    headers.forEach((h, i) => { obj[h] = String(cols[i]||'').trim(); });
    return obj;
  });
}

// --- Telefone ---
function normalizePhone(p) {
  let n = String(p||'').replace(/\D/g,'');
  if (n.startsWith('55') && n.length >= 12) n = n.slice(2);
  if (n.length === 10 || n.length === 11) return '55' + n;
  return null;
}

function isValidPhone(p) {
  const DDDS_BR = new Set([
    11,12,13,14,15,16,17,18,19,
    21,22,24,27,28,
    31,32,33,34,35,37,38,
    41,42,43,44,45,46,47,48,49,
    51,53,54,55,
    61,62,63,64,65,66,67,68,69,
    71,73,74,75,77,79,
    81,82,83,84,85,86,87,88,89,
    91,92,93,94,95,96,97,98,99
  ]);
  let n = String(p||'').replace(/\D/g,'');
  if (n.startsWith('55') && n.length >= 12) n = n.slice(2);
  if (n.length !== 10 && n.length !== 11) return false;
  const ddd = parseInt(n.slice(0,2), 10);
  const num = n.slice(2);
  if (!DDDS_BR.has(ddd)) return false;
  if (/^(\d)\1+$/.test(num)) return false;
  if (n.length === 11 && !/^9/.test(num)) return false;
  if (n.length === 10 && !/^[2-5]/.test(num)) return false;
  return true;
}

// --- Email pessoal ---
const PERSONAL_DOMAINS = new Set([
  'gmail.com','hotmail.com','hotmail.com.br','outlook.com','outlook.com.br',
  'live.com','yahoo.com','yahoo.com.br','icloud.com','me.com',
  'uol.com.br','bol.com.br','terra.com.br','ig.com.br','globo.com'
]);

function isEmailOK(e) {
  const em = String(e||'').toLowerCase().trim();
  if (!em || !em.includes('@')) return true;
  const parts = em.split('@');
  if (parts.length !== 2) return false;
  const [local, domain] = parts;
  if (!PERSONAL_DOMAINS.has(domain)) return false;
  if (/^(contato|comercial|vendas|financeiro|rh|suporte|atendimento|sac|admin|juridico|marketing|info|hello|reservas|orcamento)$/i.test(local)) return false;
  return true;
}

// --- Filtros de exclusão (somente o que DEVE ser bloqueado) ---
// Advogados e escritórios jurídicos
const RE_JURIDICO = /\b(oab|advogad[oa]|advocacia|jur[íi]dico|procurador|defensoria|escritório de advocacia)\b/i;
// Concorrentes diretos: cidadania, passaporte, visto, cartório, tradução, apostilamento
const RE_BLOQUEADO = /cidadania italiana|cidadania europeia|cidadania portuguesa|cidadania espanhola|passaporte italiano|passaporte europeu|visto europeu|passaporto italiano|dupla cidadania|regulariza[cç][aã]o de cidadania|empresa de cidadania|cart[oó]rio|tabelionato|tabeli[aã]o|registro civil|tradu[cç][aã]o juramentada|tradutor[a]? juramentad[oa]|apostilamento|apostila de haia/i;

// --- Categoria ---
const RE_ITALIA    = /bisav[o\xf4]|trisav[o\xf4]|antepassado|ascend[e\xea]ncia italiana|descendente italiano|\xe1rvore geneal\xf3gica|arvore genealogica/i;
const RE_SAUDE     = /\b(m[e\xe9]dic[oa]|enfermei[ro]|dentista|farmac[e\xea]utic[oa]|fisioterapeuta|psic[o\xf3]log[oa]|nutricionista|biom[e\xe9]dic[oa]|veterin[a\xe1]ri[oa]|cirurgi[a\xe3]o|radiologista|\bcrm\b)\b/i;
const RE_PROF      = /\b(engenheir[oa]|arquitet[oa]|contad[oa]r|economista|administrad[oa]r|gerente|diretor[a]?|professor[a]?|analista|coordenad[oa]r)\b/i;

function detectCategory(nome, profissao, obs) {
  const t = [nome, profissao, obs].join(' ');
  if (RE_ITALIA.test(t))  return 'ITALIA_SERVICOS';
  if (RE_SAUDE.test(t))   return 'SAUDE';
  if (RE_PROF.test(t))    return 'PERFIL_PROFISSIONAL';
  return 'GERAL';
}

function calcPriority(hasPhone, hasEmail, hasProfissao, categoria) {
  let p = 0;
  if (hasPhone)    p += 3;
  if (hasEmail)    p += 1;
  if (hasProfissao) p += 1;
  if (categoria === 'ITALIA_SERVICOS')    p += 4;
  if (categoria === 'SAUDE')              p += 2;
  if (categoria === 'PERFIL_PROFISSIONAL') p += 2;
  return p;
}

// --- Processar ---
const rows1 = parseCSV(csv1, detectDelimiter(csv1));
const rows2 = parseCSV(csv2, detectDelimiter(csv2));
const allRows = [...rows1, ...rows2];

const seen = new Set();
const results = [];

for (const row of allRows) {
  const nomeRaw = String(row.nome || '').trim();
  const nome = nomeRaw.replace(/\s*[|\-\u2013\u2014\u2022\/].*$/, '').trim();
  const telefoneRaw = String(row.telefone || '').trim();
  const email = String(row.email || '').toLowerCase().trim();
  const profissao = String(row.profissao || '').trim();
  const observacao = String(row.observacao || '').trim();
  const cidade = String(row.cidade || '').trim();
  const estado = String(row.estado || '').trim();

  if (!telefoneRaw) continue;
  if (!isValidPhone(telefoneRaw)) continue;

  const telefone = normalizePhone(telefoneRaw);
  if (!telefone) continue;

  if (seen.has(telefone)) continue;
  if (!nome) continue;

  const allText = [nome, profissao, observacao, email].join(' ');
  if (RE_JURIDICO.test(allText))  continue;
  if (RE_BLOQUEADO.test(allText)) continue;

  seen.add(telefone);

  const categoria = detectCategory(nome, profissao, observacao);
  const prioridade = calcPriority(!!telefone, !!email, !!profissao, categoria);

  results.push({
    json: {
      nome,
      telefone_original: telefoneRaw,
      telefone_normalizado: telefone,
      email: email || null,
      cidade: cidade || null,
      estado: estado || null,
      profissao: profissao || null,
      observacao: observacao || null,
      categoria,
      prioridade
    }
  });
}

return results;

